class Solution {
    public int minIncrementForUnique(int[] nums){
        Arrays.sort(nums);
        int moves=0;
        for(int i=1;i<nums.length;i++)if(nums[i]<=nums[i-1]){
            int required=nums[i-1]+1;
            moves+=required-nums[i];
            nums[i]=required;
        }
        return moves;
    }
}

