code.cpp:
class Solution {
    public: int minIncrementForUnique(vector<int>& nums){
        sort(nums.begin(),nums.end());
        int moves=0;
        for(int i=1;i<(int)nums.size();++i)if(nums[i]<=nums[i-1]){
            int required=nums[i-1]+1;
            moves+=required-nums[i];
            nums[i]=required;
        }
        return moves;
    }
};
